SourceCode.Declaration:
/// <summary>
/// Extension class for the WMSArrivalOverview form.
/// Provides warehouse restriction role handling and filtered arrival options for restricted users.
/// </summary>
[ExtensionOf(formStr(WMSArrivalOverview))]
final class METWMSArrivalOverview_Extension
{
}

Method.Source:
/// <summary>
/// Determines whether the current user has the warehouse restriction role.
/// </summary>
/// <returns>true if the user has the METINVENTLOCATIONPOLICYROLE role; otherwise, false.</returns>
private boolean METUserHasWarehouseRestrictionRole()
{
    SecurityRole     securityRole;
    SecurityUserRole securityUserRole;

    select firstonly RecId
        from securityRole
        where securityRole.AotName == roleStr(METINVENTLOCATIONPOLICYROLE)
        exists join securityUserRole
            where securityUserRole.SecurityRole == securityRole.RecId
               && securityUserRole.User         == curUserId();

    return securityRole.RecId != 0;
}

private void METApplyRestrictedArrivalOptions()
{
    // filtering the record types
    this.editinclPurch(true, NoYes::Yes);
    this.editinclTransfer(true, NoYes::Yes);

    this.editinclOther(true, NoYes::No);
    this.editinclReturn(true, NoYes::No);
    this.editinclProd(true, NoYes::No);
    this.editinclQuarantine(true, NoYes::No);
}

/// <summary>
/// filters the WMSArrivalOverviewTmp and WMSArrivalDetailTmp tables for users with warehouse restrictions, ensuring that only relevant records (POs and CSD TOs) are displayed to the user. It first deletes any records from the overview temp table that do not match the allowed transaction types, then removes any TO records that are not of the CSD transfer type. Finally, it deletes any detail records that do not have a corresponding overview record after the filtering is applied.
/// </summary>
private void METFilterRestrictedArrivalTmpTables()
{
    WMSArrivalOverviewTmp     overviewTmp;
    WMSArrivalOverviewTmp     remainingOverviewTmp;
    WMSArrivalDetailTmp       detailTmp;
    InventTransferTable       inventTransferTable;
    METInventTransferTableExt metInventTransferTableExt;

    overviewTmp.setTmpData(WMSArrivalOverviewTmp);
    detailTmp.setTmpData(WMSArrivalDetailTmp);

    ttsbegin;

    // remove non PO and TO records.
    delete_from overviewTmp
        where overviewTmp.InventTransType != InventTransType::Purch
           && overviewTmp.InventTransType != InventTransType::TransferOrderReceive;
    // remove TO records that are not CSD transfer type.
    delete_from overviewTmp
        where  overviewTmp.InventTransType == InventTransType::TransferOrderReceive
        exists join inventTransferTable
            where inventTransferTable.TransferId == overviewTmp.InventTransRefId
        exists join metInventTransferTableExt
            where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
                && metInventTransferTableExt.TransferType == METCrossDockTransferType::CSD;

    remainingOverviewTmp.setTmpData(overviewTmp);

    /* Remove detail lines where the parent overview/header record no longer exists.  */
    delete_from detailTmp
           notexists join remainingOverviewTmp
                where remainingOverviewTmp.InventTransRefId == detailTmp.InventTransRefId
                   && remainingOverviewTmp.InventTransType  == detailTmp.InventTransType;

    ttscommit;
    // Push filtered temp buffers back to form datasource temp buffers.
    WMSArrivalOverviewTmp.setTmpData(overviewTmp);
    WMSArrivalDetailTmp.setTmpData(detailTmp);
}

/// <summary>
/// fills the temp tables for the WMSArrivalOverview form, applying warehouse restriction filters for users with the appropriate role. If the user has the METINVENTLOCATIONPOLICYROLE role, it first applies the restricted arrival options to filter the types of transactions included in the overview. After calling the base fillTables method to populate the temp tables, it further filters the temp tables to ensure that only relevant records are displayed to restricted users. Finally, it refreshes the form's datasources and updates totals to reflect any changes from the filtering process.
/// </summary>
public void fillTables()
{
    boolean isRestrictedUser = this.METUserHasWarehouseRestrictionRole();

    if (isRestrictedUser)
    {
        this.METApplyRestrictedArrivalOptions();
    }

    next fillTables();

    this.applyWarehouseFilter();

    if (isRestrictedUser)
    {
        this.METFilterRestrictedArrivalTmpTables();

        //Refresh both temp datasources from the filtered temp data.
        WMSArrivalOverviewTmp_ds.executeQuery();
        WMSArrivalDetailTmp_ds.executeQuery();
        // Recalculate totals after filtering the temp tables.
        this.updateTotals();
    }

}

/// <summary>
/// Filters records in the WMSArrivalOverview temporary table based on the
/// warehouses assigned to the current user through warehouse security.
/// </summary>
/// <remarks>
/// Retrieves the user's authorized warehouse list, extracts warehouse IDs
/// from the site/warehouse container, and removes records whose warehouse
/// is not included in the user's allowed warehouses.
/// </remarks>
private void applyWarehouseFilter()
{
    QueryBuildDataSource qbds;
    QueryBuildRange      qbr;
    FormDataSource       fds;
    container            warehouseCon;
    Set                  warehouseSet = new Set(Types::String);
    SetEnumerator        enumerator;
    InventLocationId     warehouseId;
    str                  rangeValue;
    int                  i;

    if (!METSecurityPolicyHelper::isRoleActiveForCurrentUser(
        roleStr(METInventLocationPolicyRole)) || Global::isSystemAdministrator())
    {
        return;
    }

    // Now returns ONLY warehouseIds
    warehouseCon = METUserSecurityWarehouseList::findMultipleWarehouseByUser();

    fds = this.dataSource(formDataSourceStr(WMSArrivalOverview, WMSArrivalOverviewTmp));
    qbds = fds.queryBuildDataSource();

    // If no warehouses → block all data
    if (!conLen(warehouseCon))
    {
        qbr = SysQuery::findOrCreateRange(
        qbds,
        fieldNum(WMSArrivalOverviewTmp, RecId));

        qbr.value('0');
        fds.executeQuery();
        return;
    }

    // Build unique warehouse set
    for (i = 1; i <= conLen(warehouseCon); i++)
    {
        warehouseId = conPeek(warehouseCon, i);

        if (warehouseId)
        {
            warehouseSet.add(warehouseId);
        }
    }

    enumerator = warehouseSet.getEnumerator();

    while (enumerator.moveNext())
    {
        warehouseId = enumerator.current();

        if (rangeValue)
        {
            rangeValue += ' || ';
        }

        rangeValue += strFmt(
        '(%1 == "%2")',
        fieldStr(WMSArrivalOverviewTmp, InventLocationId),
        warehouseId);
    }

    qbr = SysQuery::findOrCreateRange(
    qbds,
    fieldNum(WMSArrivalOverviewTmp, RecId));

    qbr.value(strFmt('(%1)', rangeValue));

    fds.executeQuery();
}
